# Let's find out which process IDs are associated with the malicious GUIDs
# GruntHTTP.exe: {71b87c12-d7e5-5f84-0d01-000000000500}
# cmd.exe: {71b87c12-d9fe-5f84-1701-000000000500}
# conhost.exe: {71b87c12-d9fe-5f84-1801-000000000500}
# wuauclt.exe: {71b87c12-d9fe-5f84-1901-000000000500}
# notepad.exe: {71b87c12-d9fe-5f84-1a01-000000000500}

# We saw in earlier logs:
# GruntHTTP.exe PID: 3356 (0xd1c)
# cmd.exe PID: 3148 (0xc4c)
# wuauclt.exe PID: 6208 (0x1840)
# notepad.exe PID: 2368 (0x940) or similar?
# Let's extract the exact PIDs (both decimal and hex) from the database for these GUIDs

import re

pid_to_name = {}
pids = set() # decimal
hex_pids = set() # hex format used in Security logs (e.g. 0x1a4)

for ev in events:
    eid = ev['event_id']
    if eid in malicious_ids:
        # Let's extract ProcessId from message
        msg = ev.get('message', '') or ''
        for m in re.finditer(r'ProcessId:\s*(\d+)', msg):
            pid = int(m.group(1))
            pids.add(pid)
            hex_pids.add(f"0x{pid:x}")
        for m in re.finditer(r'SourceProcessId:\s*(\d+)', msg):
            pid = int(m.group(1))
            pids.add(pid)
            hex_pids.add(f"0x{pid:x}")
        for m in re.finditer(r'TargetProcessId:\s*(\d+)', msg):
            pid = int(m.group(1))
            pids.add(pid)
            hex_pids.add(f"0x{pid:x}")

print("Malicious PIDs (decimal):", pids)
print("Malicious PIDs (hex):", hex_pids)

# Now let's scan the remaining events and see if any of them mention these PIDs
additional_malicious = set()
for ev in events:
    eid = ev['event_id']
    if eid in malicious_ids:
        continue

    msg = ev.get('message', '') or ''
    # Check if any malicious PID (decimal or hex) is mentioned in the message or details
    # Be careful to match them with word boundaries to avoid matching sub-strings
    found = False
    for pid in pids:
        if re.search(r'\b' + str(pid) + r'\b', msg):
            found = True
            break
    if not found:
        for hpid in hex_pids:
            if re.search(r'\b' + hpid + r'\b', msg, re.IGNORECASE):
                found = True
                break

    if found:
        additional_malicious.add(eid)

print(f"Found {len(additional_malicious)} additional malicious events by PID correlation.")

# Let's print the events that are STILL not classified as malicious so we can inspect them
non_malicious_events = []
for ev in events:
    eid = ev['event_id']
    if eid not in malicious_ids and eid not in additional_malicious:
        non_malicious_events.append(ev)

print(f"Remaining non-malicious events on WS-05: {len(non_malicious_events)}")
for ev in non_malicious_events[:20]:
    print(f"{ev['event_id']} | {ev['event_code']} | {ev['timestamp']} | {ev['image']} | {ev['message'][:100].replace('\n', ' ')}")

# Merge additional ones
malicious_ids.update(additional_malicious)
with open('/tmp/suspects.json', 'w') as f:
    json.dump(sorted(list(malicious_ids)), f, indent=2)

EOF
